from html.parser import HTMLParser
from pathlib import Path
import json
import re

class Page(HTMLParser):
    def __init__(self):
        super().__init__()
        self.tags = []
        self.text = []
        self.title = []
        self.in_title = False
        self.ids = set()
        self.links = []
        self.viewport = False
        self.services = {}
        self.service_text = {}
        self.current_service = None
    def handle_starttag(self, tag, attrs):
        values = dict(attrs)
        self.tags.append(tag)
        self.in_title = self.in_title or tag == 'title'
        if values.get('id'):
            self.ids.add(values['id'])
        if tag == 'meta' and values.get('name') == 'viewport':
            self.viewport = True
        if tag == 'a':
            self.links.append(values.get('href', ''))
        if tag == 'article' and values.get('data-service'):
            key = values['data-service']
            assert key not in self.services, 'Duplicate service article'
            self.services[key] = int(values['data-price'])
            self.service_text[key] = []
            self.current_service = key
        for name in ['src', 'href']:
            assert not values.get(name, '').startswith(('http:', 'https:', '//')), 'External asset or destination is forbidden'
    def handle_endtag(self, tag):
        if tag == 'title':
            self.in_title = False
        if tag == 'article':
            self.current_service = None
    def handle_data(self, text):
        self.text.append(text)
        if self.current_service is not None:
            self.service_text[self.current_service].append(text)
        if self.in_title:
            self.title.append(text)

source = Path('index.html').read_text(encoding='utf-8')
page = Page()
page.feed(source)
text = ' '.join(page.text)
assert ''.join(page.title).strip() == 'Solder & Spoke | Bicycle repair'
for expected in ['Solder & Spoke', 'Brake tune', '$28', 'Flat repair', '$18', 'Safety check', '$0', 'Tuesday', 'Saturday', '18 Mill Lane']:
    assert expected in text, expected
for tag in ['html', 'head', 'body', 'main', 'nav', 'h1']:
    assert tag in page.tags, tag
assert {'services', 'visit'} <= page.ids
assert '#visit' in page.links
assert page.services == {'brake-tune': 28, 'flat-repair': 18, 'safety-check': 0}
for key, label in [('brake-tune', 'Brake tune'), ('flat-repair', 'Flat repair'), ('safety-check', 'Safety check')]:
    service_text = ' '.join(page.service_text[key])
    assert label in service_text and '$' + str(page.services[key]) in service_text
assert page.viewport
assert '@media' in source
assert 'prefers-reduced-motion' in source
assert re.search(r'(?:max-width|min-width)\s*:', source)
report = {'page': 'index.html', 'title': ''.join(page.title).strip(), 'service_count': len(page.services), 'prices': ['$' + str(price) for price in sorted(page.services.values())], 'layout_checks': ['viewport', 'mobile-media-query', 'reduced-motion']}
Path('frontend-verification.json').write_text(json.dumps(report, sort_keys=True) + '\n', encoding='utf-8')
print('Validated Solder & Spoke with 3 priced services')

